import React, { useState, useEffect } from 'react';
import API from '../api/axios';
import {
  ShieldCheck,
  Plus,
  Trash2,
  Lock,
  Mail,
  Phone,
  UserCheck,
  UserX,
  X,
  CheckCircle,
  AlertTriangle,
  RefreshCw,
  Key
} from 'lucide-react';

export default function AdminRoles() {
  const [admins, setAdmins] = useState([]);
  const [loading, setLoading] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [deleteConfirm, setDeleteConfirm] = useState({ open: false, id: null, name: '' });

  // অন-স্ক্রিন টোস্ট নোটিফিকেশন স্টেট
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' });

  // নতুন সাব অ্যাডমিন ফর্ম স্টেট
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    password: '',
    role: 'sub_admin',
    permissions: ['orders', 'restaurants']
  });

  const availablePermissions = [
    { id: 'orders', label: 'Live Orders Manage' },
    { id: 'restaurants', label: 'Restaurants Control' },
    { id: 'riders', label: 'Riders & Cash' },
    { id: 'master_edit', label: 'Master Edit (Banners/Settings)' },
    { id: 'finance', label: 'Finance & Payouts' },
    { id: 'customers', label: 'Customer Control' }
  ];

  const showToast = (message, type = 'success') => {
    setToast({ show: true, message, type });
    setTimeout(() => {
      setToast({ show: false, message: '', type: 'success' });
    }, 3200);
  };

  const fetchAdmins = async () => {
    try {
      setLoading(true);
      const res = await API.get('/admins');
      setAdmins(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      showToast('অ্যাডমিন ডাটা লোড করা যায়নি!', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAdmins();
  }, []);

  const handlePermissionToggle = (permId) => {
    setFormData((prev) => {
      const exists = prev.permissions.includes(permId);
      return {
        ...prev,
        permissions: exists
          ? prev.permissions.filter((p) => p !== permId)
          : [...prev.permissions, permId]
      };
    });
  };

  // সাব-অ্যাডমিন তৈরির হ্যান্ডলার
  const handleAddSubAdmin = async (e) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.password) {
      showToast('নাম, ইমেইল এবং পাসওয়ার্ড পূরণ করুন!', 'error');
      return;
    }

    try {
      const res = await API.post('/admins', formData);
      if (res.data) {
        setAdmins((prev) => [res.data, ...prev]);
        setIsModalOpen(false);
        setFormData({
          name: '',
          email: '',
          phone: '',
          password: '',
          role: 'sub_admin',
          permissions: ['orders', 'restaurants']
        });
        showToast('নতুন সাব-অ্যাডমিন সফলভাবে যুক্ত হয়েছে!');
      }
    } catch (err) {
      const errMsg = err.response?.data?.error || err.message;
      showToast(`সাব-অ্যাডমিন সেভ করা যায়নি: ${errMsg}`, 'error');
    }
  };

  // স্ট্যাটাস টগল (Active / Blocked)
  const handleToggleStatus = async (id, currentStatus, name) => {
    try {
      const res = await API.patch(`/admins/${id}/toggle-status`);
      if (res.data) {
        setAdmins((prev) =>
          prev.map((a) => (a.id === id ? { ...a, status: res.data.status } : a))
        );
        showToast(`${name} এর স্ট্যাটাস আপডেট হয়েছে!`);
      }
    } catch (err) {
      showToast('স্ট্যাটাস পরিবর্তন ব্যর্থ হয়েছে!', 'error');
    }
  };

  // ডিলিট হ্যান্ডলার
  const confirmDeleteAdmin = async () => {
    if (!deleteConfirm.id) return;
    try {
      await API.delete(`/admins/${deleteConfirm.id}`);
      setAdmins((prev) => prev.filter((a) => a.id !== deleteConfirm.id));
      setDeleteConfirm({ open: false, id: null, name: '' });
      showToast('সাব-অ্যাডমিন ডিলিট করা হয়েছে!');
    } catch (err) {
      showToast('ডিলিট করা যায়নি!', 'error');
    }
  };

  return (
    <div className="p-8 space-y-6 bg-gray-50 min-h-screen relative font-sans">

      {/* অন-স্ক্রিন অ্যানিমেটেড টোস্ট নোটিফিকেশন */}
      {toast.show && (
        <div className="fixed top-6 right-6 z-50 transition-all duration-300 transform translate-y-0 opacity-100">
          <div
            className={`flex items-center gap-3 px-5 py-3.5 rounded-2xl shadow-xl border text-sm font-bold backdrop-blur-md ${
              toast.type === 'error'
                ? 'bg-red-500/90 text-white border-red-600 shadow-red-500/20'
                : 'bg-emerald-600/95 text-white border-emerald-700 shadow-emerald-600/20'
            }`}
          >
            {toast.type === 'error' ? <AlertTriangle className="w-5 h-5" /> : <CheckCircle className="w-5 h-5" />}
            <span>{toast.message}</span>
          </div>
        </div>
      )}

      {/* হেডার */}
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-900 tracking-tight">Admin Roles & Permissions</h1>
          <p className="text-sm text-gray-500">সাব-অ্যাডমিন তৈরি করুন, পারমিশন কন্ট্রোল করুন এবং অ্যাক্সেস ম্যানেজ করুন</p>
        </div>

        <div className="flex items-center gap-3">
          <button
            onClick={fetchAdmins}
            className="p-2.5 bg-white border border-gray-200 rounded-xl hover:text-emerald-600 transition-colors shadow-sm"
            title="Refresh List"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin text-emerald-600' : ''}`} />
          </button>

          {/* এই বাটনটি মোডাল ওপেন করবে */}
          <button
            type="button"
            onClick={() => setIsModalOpen(true)}
            className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-700 shadow-md shadow-emerald-600/20 text-sm transition-transform active:scale-95 cursor-pointer"
          >
            <Plus className="w-4 h-4" /> Add Sub Admin
          </button>
        </div>
      </div>

      {/* অ্যাডমিন কার্ড গ্রিড */}
      {loading ? (
        <div className="p-12 text-center text-gray-400 font-bold">ডাটা লোড হচ্ছে...</div>
      ) : admins.length === 0 ? (
        <div className="bg-white p-12 text-center rounded-2xl border border-dashed border-gray-300">
          <ShieldCheck className="w-10 h-10 text-gray-300 mx-auto mb-2" />
          <p className="text-gray-500 font-semibold text-sm">কোনো সাব-অ্যাডমিন তৈরি করা নেই। "+ Add Sub Admin" বাটনে ক্লিক করে যুক্ত করুন।</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {admins.map((a) => {
            const isActive = a.status === 'active';
            const isSuper = a.role === 'super_admin';

            return (
              <div
                key={a.id}
                className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm space-y-4 hover:shadow-md transition-shadow relative"
              >
                {!isSuper && (
                  <button
                    onClick={() => setDeleteConfirm({ open: true, id: a.id, name: a.name })}
                    className="absolute top-5 right-5 text-gray-300 hover:text-red-600 transition-colors"
                    title="Delete"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                )}

                <div className="flex items-center gap-3.5 pr-6">
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-bold ${
                    isSuper ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'
                  }`}>
                    <ShieldCheck className="w-6 h-6" />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="font-bold text-gray-900 text-base">{a.name}</h3>
                      <span
                        className={`text-[10px] font-black px-2 py-0.5 rounded-md uppercase tracking-wider ${
                          isSuper
                            ? 'bg-purple-100 text-purple-700'
                            : isActive
                            ? 'bg-emerald-100 text-emerald-800'
                            : 'bg-red-100 text-red-700'
                        }`}
                      >
                        {isSuper ? 'SUPER ADMIN' : isActive ? 'ACTIVE' : 'BLOCKED'}
                      </span>
                    </div>
                    <p className="text-xs text-gray-500 flex items-center gap-1 mt-0.5">
                      <Mail className="w-3 h-3 text-gray-400" /> {a.email}
                    </p>
                    {a.phone && (
                      <p className="text-xs text-gray-400 flex items-center gap-1 mt-0.5">
                        <Phone className="w-3 h-3 text-gray-300" /> {a.phone}
                      </p>
                    )}
                  </div>
                </div>

                {/* পারমিশন লিস্ট */}
                <div className="bg-gray-50 p-3.5 rounded-xl border border-gray-100 space-y-1.5">
                  <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block">
                    Access Permissions:
                  </span>
                  <div className="flex flex-wrap gap-1.5">
                    {a.permissions && a.permissions.length > 0 ? (
                      a.permissions.map((p, idx) => (
                        <span
                          key={idx}
                          className="px-2 py-0.5 bg-white border border-gray-200 text-gray-700 rounded-md text-[11px] font-bold"
                        >
                          {p}
                        </span>
                      ))
                    ) : (
                      <span className="text-xs text-gray-400 italic">No specific permissions</span>
                    )}
                  </div>
                </div>

                {/* স্ট্যাটাস বাটন */}
                {!isSuper && (
                  <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                    <span className="text-xs text-gray-400 font-semibold">Account Status:</span>
                    <button
                      onClick={() => handleToggleStatus(a.id, a.status, a.name)}
                      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold transition-all ${
                        isActive
                          ? 'bg-amber-50 text-amber-700 border border-amber-200 hover:bg-amber-100'
                          : 'bg-emerald-50 text-emerald-700 border border-emerald-200 hover:bg-emerald-100'
                      }`}
                    >
                      {isActive ? (
                        <>
                          <UserX className="w-3.5 h-3.5" /> Block Sub Admin
                        </>
                      ) : (
                        <>
                          <UserCheck className="w-3.5 h-3.5" /> Activate Admin
                        </>
                      )}
                    </button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* ===================== অন-স্ক্রিন মোডাল (Add Sub Admin) ===================== */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4 z-50 animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl p-6 max-w-md w-full shadow-2xl space-y-4 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center border-b pb-3">
              <h3 className="font-bold text-gray-900 text-base flex items-center gap-2">
                <ShieldCheck className="w-5 h-5 text-emerald-600" />
                Add New Sub Admin
              </h3>
              <button
                type="button"
                onClick={() => setIsModalOpen(false)}
                className="p-1 text-gray-400 hover:text-black rounded-lg hover:bg-gray-100"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleAddSubAdmin} className="space-y-3.5 text-xs font-medium">
              <div>
                <label className="block mb-1 text-gray-600 font-bold">Sub Admin Name</label>
                <input
                  type="text"
                  required
                  placeholder="e.g. Asif Mahmud"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className="w-full px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-1 focus:ring-emerald-500 font-semibold text-sm"
                />
              </div>

              <div>
                <label className="block mb-1 text-gray-600 font-bold">Email Address</label>
                <input
                  type="email"
                  required
                  placeholder="asif@cityfood.com"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="w-full px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-1 focus:ring-emerald-500 font-semibold text-sm"
                />
              </div>

              <div>
                <label className="block mb-1 text-gray-600 font-bold">Contact Phone Number</label>
                <input
                  type="text"
                  placeholder="017xxxxxxxx"
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  className="w-full px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-1 focus:ring-emerald-500 font-semibold text-sm"
                />
              </div>

              <div>
                <label className="block mb-1 text-gray-600 font-bold">Account Password</label>
                <input
                  type="password"
                  required
                  placeholder="Password for login"
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  className="w-full px-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-1 focus:ring-emerald-500 font-semibold text-sm"
                />
              </div>

              {/* পারমিশন সিলেকশন বক্স */}
              <div className="pt-1">
                <label className="block mb-2 text-gray-700 font-bold">Allowed Permissions:</label>
                <div className="grid grid-cols-2 gap-2 bg-gray-50 p-3 rounded-2xl border border-gray-200">
                  {availablePermissions.map((perm) => {
                    const isChecked = formData.permissions.includes(perm.id);
                    return (
                      <label
                        key={perm.id}
                        className={`flex items-center gap-2 p-2 rounded-xl border text-[11px] font-bold cursor-pointer transition-all ${
                          isChecked
                            ? 'bg-emerald-50 border-emerald-300 text-emerald-800'
                            : 'bg-white border-gray-200 text-gray-500 hover:bg-gray-100'
                        }`}
                      >
                        <input
                          type="checkbox"
                          checked={isChecked}
                          onChange={() => handlePermissionToggle(perm.id)}
                          className="rounded text-emerald-600 focus:ring-0"
                        />
                        <span>{perm.label}</span>
                      </label>
                    );
                  })}
                </div>
              </div>

              <button
                type="submit"
                className="w-full py-2.5 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-700 shadow-md shadow-emerald-600/20 text-sm active:scale-95 transition-transform mt-2 cursor-pointer"
              >
                Create & Assign Sub Admin
              </button>
            </form>
          </div>
        </div>
      )}

      {/* ===================== ডিলিট কনফার্মেশন মোডাল ===================== */}
      {deleteConfirm.open && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4 z-50 animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl p-6 max-w-sm w-full shadow-2xl text-center space-y-4">
            <div className="w-14 h-14 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto">
              <Trash2 className="w-7 h-7" />
            </div>
            <div>
              <h3 className="text-lg font-black text-gray-900">Confirm Deletion</h3>
              <p className="text-xs text-gray-500 mt-1 leading-relaxed">
                আপনি কি নিশ্চিত <strong>"{deleteConfirm.name}"</strong> সাব-অ্যাডমিন ডিলিট করতে চান?
              </p>
            </div>
            <div className="flex gap-2 pt-2">
              <button
                type="button"
                onClick={() => setDeleteConfirm({ open: false, id: null, name: '' })}
                className="flex-1 py-2.5 bg-gray-100 text-gray-700 font-bold rounded-xl text-xs hover:bg-gray-200"
              >
                বাতিল
              </button>
              <button
                type="button"
                onClick={confirmDeleteAdmin}
                className="flex-1 py-2.5 bg-red-600 text-white font-bold rounded-xl text-xs hover:bg-red-700 shadow-md shadow-red-600/30"
              >
                ডিলিট করুন
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
